package com.matthewmariner.prayerhitsplats;

import java.util.HashMap;
import java.util.Map;

/**
 * Projectiles aimed at you, kept until a tick after they land, together with the protection
 * prayers up on the tick each was fired: one of the two moments a hit is judged by, the other being
 * the tick it lands.
 */
final class Landings
{
	/** A projectile lands on the tick its hitsplat does: within 30 client cycles, either side. */
	static final int TOLERANCE = 30;

	/** What {@link #take} returns when no projectile landed with the hit. */
	static final int NONE = -1;

	private static final class Landing
	{
		private int prayers = NONE;
		private int end;
		private boolean taken;
	}

	/**
	 * Keyed by the projectile because the client reports one more than once; its landing cycle follows each report.
	 * A taken one stays until it is past {@link #TOLERANCE}, so a report of it in flight is not a new projectile.
	 */
	private final Map<Object, Landing> landings = new HashMap<>();

	void aimed(Object projectile, int endCycle)
	{
		landings.computeIfAbsent(projectile, p -> new Landing()).end = endCycle;
	}

	/**
	 * Gives every projectile first seen this tick the prayers the server had up by its end, and
	 * forgets any that landed over a tick ago, so a projectile that never brings a hit is not kept.
	 * A taken projectile keeps what it had.
	 */
	void settle(int prayers, int now)
	{
		forget(now);
		for (Landing landing : landings.values())
		{
			if (!landing.taken && landing.prayers == NONE)
			{
				landing.prayers = prayers;
			}
		}
	}

	/**
	 * Takes the projectile landing nearest {@code now}, within a tick of it; of two as near, the
	 * earlier. Each is taken once, so a pair landing together is one hit each.
	 *
	 * @return the prayers up on the tick it was fired, or {@link #NONE}
	 */
	int take(int now)
	{
		forget(now);
		Landing nearest = null;
		for (Landing landing : landings.values())
		{
			if (landing.taken || landing.end > now + TOLERANCE)
			{
				continue;
			}
			int away = Math.abs(landing.end - now);
			int nearestAway = nearest == null ? 0 : Math.abs(nearest.end - now);
			if (nearest == null || away < nearestAway || away == nearestAway && landing.end < nearest.end)
			{
				nearest = landing;
			}
		}
		if (nearest == null)
		{
			return NONE;
		}
		nearest.taken = true;
		return nearest.prayers;
	}

	private void forget(int now)
	{
		landings.values().removeIf(landing -> landing.end < now - TOLERANCE);
	}
}

package com.matthewmariner.prayerhitsplats;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("prayerhitsplats")
public interface PrayerHitsplatsConfig extends Config
{
	@ConfigItem(
		keyName = "colour",
		name = "Colour",
		description = "Colour of a 0 taken while praying against the attack"
	)
	default Color colour()
	{
		return new Color(255, 176, 0);
	}
}

package com.matthewmariner.prayerhitsplats;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.ImageUtil;

/**
 * Draws a recoloured 0 over the client's own blue one, in the same slot, for as long as it shows.
 */
class PrayerHitsplatsOverlay extends Overlay
{
	/** Where the client draws each hitsplat slot, relative to the first. */
	private static final int[][] SLOT_OFFSETS = {{0, 0}, {0, -20}, {-15, -10}, {15, -10}};

	private final Client client;
	private final PrayerHitsplatsConfig config;
	private final SpriteManager spriteManager;

	/** Game cycle each slot's tint lasts until; 0 when the slot holds nothing to tint. */
	private final int[] tintedUntil = new int[SplatSlots.COUNT];
	private BufferedImage cover;
	private Color coverColour;

	@Inject
	PrayerHitsplatsOverlay(Client client, PrayerHitsplatsConfig config, SpriteManager spriteManager)
	{
		this.client = client;
		this.config = config;
		this.spriteManager = spriteManager;
		setPosition(OverlayPosition.DYNAMIC);
		// Above the client's own hitsplats ("above overheads"), beneath the interfaces.
		setLayer(OverlayLayer.UNDER_WIDGETS);
	}

	void tint(int slot, int until)
	{
		tintedUntil[slot] = until;
	}

	void clear()
	{
		Arrays.fill(tintedUntil, 0);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		int now = client.getGameCycle();
		if (!tinting(now))
		{
			return null;
		}

		Player player = client.getLocalPlayer();
		BufferedImage image = cover();
		if (player == null || image == null)
		{
			return null;
		}

		Point anchor = player.getCanvasImageLocation(image, player.getLogicalHeight() / 2);
		if (anchor == null)
		{
			return null;
		}

		for (int slot = 0; slot < SplatSlots.COUNT; slot++)
		{
			if (tintedUntil[slot] > now)
			{
				graphics.drawImage(image, anchor.getX() + SLOT_OFFSETS[slot][0], anchor.getY() + SLOT_OFFSETS[slot][1], null);
			}
		}
		return null;
	}

	private boolean tinting(int now)
	{
		for (int until : tintedUntil)
		{
			if (until > now)
			{
				return true;
			}
		}
		return false;
	}

	private BufferedImage cover()
	{
		Color colour = config.colour();
		if (cover == null || !colour.equals(coverColour))
		{
			BufferedImage sprite = spriteManager.getSprite(SpriteID.Hitmark.HITSPLAT_BLUE_MISS, 0);
			if (sprite == null)
			{
				return null;
			}
			cover = cover(sprite, colour);
			coverColour = colour;
		}
		return cover;
	}

	/**
	 * The miss splat in {@code colour} with its 0, and a 1px rim so a pixel of offset from the
	 * splat underneath cannot show through.
	 */
	private static BufferedImage cover(BufferedImage sprite, Color colour)
	{
		BufferedImage padded = new BufferedImage(sprite.getWidth() + 2, sprite.getHeight() + 2, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = padded.createGraphics();
		g.drawImage(tint(sprite, colour), 1, 1, null);
		g.dispose();

		BufferedImage image = ImageUtil.outlineImage(padded, colour.darker());
		g = image.createGraphics();
		g.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics metrics = g.getFontMetrics();
		int x = (image.getWidth() - metrics.stringWidth("0")) / 2;
		int y = (image.getHeight() - metrics.getHeight()) / 2 + metrics.getAscent();
		g.setColor(Color.BLACK);
		g.drawString("0", x + 1, y + 1);
		g.setColor(Color.WHITE);
		g.drawString("0", x, y);
		g.dispose();
		return image;
	}

	/** {@code sprite} in the hue of {@code colour}, each pixel keeping its own brightness and alpha. */
	static BufferedImage tint(BufferedImage sprite, Color colour)
	{
		float[] hsb = Color.RGBtoHSB(colour.getRed(), colour.getGreen(), colour.getBlue(), null);
		BufferedImage tinted = new BufferedImage(sprite.getWidth(), sprite.getHeight(), BufferedImage.TYPE_INT_ARGB);
		for (int x = 0; x < sprite.getWidth(); x++)
		{
			for (int y = 0; y < sprite.getHeight(); y++)
			{
				int argb = sprite.getRGB(x, y);
				float brightness = Math.max(argb >> 16 & 0xFF, Math.max(argb >> 8 & 0xFF, argb & 0xFF)) / 255f;
				int rgb = Color.HSBtoRGB(hsb[0], hsb[1], hsb[2] * brightness) & 0xFFFFFF;
				tinted.setRGB(x, y, argb & 0xFF000000 | rgb);
			}
		}
		return tinted;
	}
}

package com.matthewmariner.prayerhitsplats;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Stream;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Hitsplat;
import net.runelite.api.HitsplatID;
import net.runelite.api.Player;
import net.runelite.api.Projectile;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.ProjectileMoved;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

/**
 * A 0 means the attack missed or a protection prayer stopped it, and the game draws both the same.
 * This recolours the second kind, so a blue 0 on you is a real miss.
 */
@PluginDescriptor(
	name = "Prayer Hitsplats",
	description = "Recolours the 0 you take while praying against the attack, so it no longer looks like a plain miss",
	tags = {"prayer", "protection", "hitsplat", "miss", "block", "combat"}
)
public class PrayerHitsplatsPlugin extends Plugin
{
	/** Bits of a protection-prayer mask. */
	static final int MELEE = 1, MISSILES = 2, MAGIC = 4;

	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private PrayerHitsplatsOverlay overlay;

	private final SplatSlots slots = new SplatSlots();
	private final Landings landings = new Landings();

	/**
	 * This tick's hitsplats on you, judged once the tick ends: your own hitsplats arrive before the
	 * tick's attacker positions and targets, so an attacker's first swing is not visible at the hit.
	 * The prayers are read then too, which counts a click the server took on that same tick.
	 */
	private final List<Hit> hits = new ArrayList<>();

	private static final class Hit
	{
		private final Hitsplat hitsplat;
		private final int slot, cycle;

		private Hit(Hitsplat hitsplat, int slot, int cycle)
		{
			this.hitsplat = hitsplat;
			this.slot = slot;
			this.cycle = cycle;
		}
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlay.clear();
		hits.clear();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		// GameTick follows all of a tick's packets, so a projectile first seen since the last one was fired on this tick.
		landings.settle(protection(), client.getGameCycle());

		Player player = client.getLocalPlayer();
		if (player != null)
		{
			hits.forEach(hit -> judge(hit, player));
		}
		hits.clear();
	}

	@Subscribe
	public void onProjectileMoved(ProjectileMoved event)
	{
		Projectile projectile = event.getProjectile();
		if (projectile.getTargetActor() == client.getLocalPlayer())
		{
			landings.aimed(projectile, projectile.getEndCycle());
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (event.getActor() != client.getLocalPlayer())
		{
			return;
		}

		Hitsplat hitsplat = event.getHitsplat();
		int now = client.getGameCycle();
		// Every hitsplat on you is placed, tinted or not, so the slots stay in step with the client's.
		hits.add(new Hit(hitsplat, slots.place(now, hitsplat.getDisappearsOnGameCycle()), now));
	}

	private void judge(Hit hit, Player player)
	{
		Hitsplat hitsplat = hit.hitsplat;
		// isMine() is an attack's hit or block on you, never poison and the like: only it can take a projectile.
		if (!hitsplat.isMine())
		{
			return;
		}

		int fired = landings.take(hit.cycle);
		if (hit.slot == SplatSlots.UNKNOWN || hitsplat.getHitsplatType() != HitsplatID.BLOCK_ME)
		{
			return;
		}

		boolean stopped = fired == Landings.NONE
			? prayedAgainst(attackerInMeleeReach(player), protection())
			: prayedAgainstProjectile(fired, protection());
		if (stopped)
		{
			overlay.tint(hit.slot, hitsplat.getDisappearsOnGameCycle());
		}
	}

	/**
	 * For a hit with no projectile. Melee is told apart from ranged and magic, but ranged and magic
	 * are not told apart, so either of their prayers counts against both.
	 */
	static boolean prayedAgainst(boolean melee, int prayers)
	{
		return (prayers & (melee ? MELEE : MISSILES | MAGIC)) != 0;
	}

	/**
	 * Any protection prayer up when the projectile was fired or when it landed. A monster judges at
	 * one moment or the other and the plugin does not know which, nor the attack's style.
	 */
	static boolean prayedAgainstProjectile(int fired, int landed)
	{
		return (fired | landed) != 0;
	}

	/** A hit with no projectile was melee only if something attacking you stands where melee reaches. */
	private boolean attackerInMeleeReach(Player player)
	{
		WorldArea area = player.getWorldArea();
		WorldView view = client.getTopLevelWorldView();
		return Stream.<Actor>concat(view.npcs().stream(), view.players().stream())
			.anyMatch(actor -> actor.getInteracting() == player && actor.getWorldArea().isInMeleeDistance(area));
	}

	/** The protection prayers the server has up. Never the client's values: it flips a prayer's varbit on click, before the server agrees. */
	private int protection()
	{
		return (up(VarbitID.PRAYER_PROTECTFROMMELEE) ? MELEE : 0)
			| (up(VarbitID.PRAYER_PROTECTFROMMISSILES) ? MISSILES : 0)
			| (up(VarbitID.PRAYER_PROTECTFROMMAGIC) ? MAGIC : 0);
	}

	private boolean up(int varbit)
	{
		return client.getServerVarbitValue(varbit) == 1;
	}

	@Provides
	PrayerHitsplatsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PrayerHitsplatsConfig.class);
	}
}

package com.matthewmariner.prayerhitsplats;

import java.util.Arrays;

/**
 * Which of an actor's four hitsplat slots the client draws each new hitsplat in. The API says when
 * a hitsplat disappears but not where it is drawn, so the slot is replayed from every hitsplat the
 * actor receives: round-robin over the free slots, restarting at the first once all are free.
 */
final class SplatSlots
{
	static final int COUNT = 4;

	/** What {@link #place} returns when the slot cannot be known. */
	static final int UNKNOWN = -1;

	private final int[] ends = new int[COUNT];
	private int next;

	/**
	 * @param now game cycle the hitsplat was applied on
	 * @param end game cycle it disappears on
	 * @return the slot it is drawn in, or {@link #UNKNOWN}
	 */
	int place(int now, int end)
	{
		if (allFree(now))
		{
			next = 0;
		}

		for (int i = 0; i < COUNT; i++)
		{
			int slot = next;
			next = (next + 1) % COUNT;
			if (ends[slot] <= now)
			{
				ends[slot] = end;
				return slot;
			}
		}

		// All four show, and whether the client drops this one or replaces another is not in the
		// API, so every slot counts as unknown until all of them have cleared.
		Arrays.fill(ends, Math.max(end, Arrays.stream(ends).max().getAsInt()));
		return UNKNOWN;
	}

	private boolean allFree(int now)
	{
		for (int end : ends)
		{
			if (end > now)
			{
				return false;
			}
		}
		return true;
	}
}

package com.matthewmariner.prayerhitsplats;

import static com.matthewmariner.prayerhitsplats.PrayerHitsplatsPlugin.MAGIC;
import static com.matthewmariner.prayerhitsplats.PrayerHitsplatsPlugin.MELEE;
import static com.matthewmariner.prayerhitsplats.PrayerHitsplatsPlugin.MISSILES;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class LandingsTest
{
	private final Landings landings = new Landings();

	@Test
	public void aProjectileLandingWithTheHitIsTakenOnce()
	{
		landings.aimed("arrow", 130);
		landings.settle(MISSILES, 100);

		assertEquals(MISSILES, landings.take(120));
		assertEquals(Landings.NONE, landings.take(120));
	}

	@Test
	public void aProjectileStillInFlightIsNotTaken()
	{
		landings.aimed("bolt", 200);
		landings.settle(MISSILES, 100);

		assertEquals(Landings.NONE, landings.take(200 - Landings.TOLERANCE - 1));
		assertEquals(MISSILES, landings.take(200));
	}

	@Test
	public void aProjectileLandingAFullToleranceAfterTheHitIsTaken()
	{
		landings.aimed("a", 100 + Landings.TOLERANCE);
		landings.settle(MELEE, 100);

		assertEquals(MELEE, landings.take(100));
	}

	@Test
	public void aProjectileThatLandedTicksAgoIsForgotten()
	{
		landings.aimed("spell", 100);
		landings.settle(MAGIC, 100);

		assertEquals(Landings.NONE, landings.take(100 + Landings.TOLERANCE + 1));
	}

	@Test
	public void aProjectileThatLandedAFullToleranceBeforeTheHitIsStillTaken()
	{
		landings.aimed("a", 100);
		landings.settle(MELEE, 90);

		assertEquals(MELEE, landings.take(100 + Landings.TOLERANCE));
	}

	@Test
	public void aProjectileKeepsThePrayersFromTheTickItWasFired()
	{
		Object spell = new Object();
		landings.aimed(spell, 140);
		landings.settle(MAGIC, 100);
		// Reported again a tick later, after the prayer was flicked off.
		landings.aimed(spell, 150);
		landings.settle(0, 100);

		assertEquals(MAGIC, landings.take(150));
		assertEquals(Landings.NONE, landings.take(150));
	}

	@Test
	public void aProjectileThatNeverBringsAHitIsForgottenATickAfterItLands()
	{
		landings.aimed("cosmetic", 100);
		landings.settle(MAGIC, 100 + Landings.TOLERANCE + 1);

		// Asked about its own landing cycle, it would still match if it had been kept.
		assertEquals(Landings.NONE, landings.take(100));
	}

	@Test
	public void twoProjectilesLandingTogetherAreTakenOneHitEach()
	{
		landings.aimed("first arrow", 130);
		landings.aimed("second arrow", 131);
		landings.settle(MISSILES, 100);

		assertEquals(MISSILES, landings.take(130));
		assertEquals(MISSILES, landings.take(130));
		assertEquals(Landings.NONE, landings.take(130));
	}

	@Test
	public void aPairLandingAFullToleranceApartIsTakenNearestFirst()
	{
		// "a" sorts ahead of "b" in the map, so a first-match take reaches the later orb first.
		landings.aimed("b", 130);
		landings.settle(MISSILES, 100);
		landings.aimed("a", 130 + Landings.TOLERANCE);
		landings.settle(MAGIC, 101);

		// The first hit is in reach of both orbs but belongs to the one landing beside it.
		assertEquals(MISSILES, landings.take(135));
		assertEquals(MAGIC, landings.take(135 + Landings.TOLERANCE));
		assertEquals(Landings.NONE, landings.take(135 + Landings.TOLERANCE));
	}

	@Test
	public void theNearestProjectileIsTakenWhicheverWasAimedFirst()
	{
		// "a" sorts ahead of "b" in the map, so the far one is what a first-match take would reach.
		landings.aimed("a", 150);
		landings.settle(MAGIC, 100);
		landings.aimed("b", 130);
		landings.settle(MISSILES, 101);

		assertEquals(MISSILES, landings.take(128));
		assertEquals(MAGIC, landings.take(128));
	}

	@Test
	public void theNearerLandingWinsEvenWhenTheFartherOneLandedFirst()
	{
		// The far one landed before the hit and the near one lands after it, so only the distance
		// picks, not which side of the hit it is on.
		landings.aimed("a", 120);
		landings.settle(MAGIC, 100);
		landings.aimed("b", 135);
		landings.settle(MISSILES, 101);

		assertEquals(MISSILES, landings.take(130));
		assertEquals(MAGIC, landings.take(130));
	}

	@Test
	public void aTieGoesToTheEarlierLanding()
	{
		landings.aimed("a", 140);
		landings.settle(MAGIC, 100);
		landings.aimed("b", 120);
		landings.settle(MISSILES, 101);

		assertEquals(MISSILES, landings.take(130));
		assertEquals(MAGIC, landings.take(130));
	}

	@Test
	public void aTieGoesToTheEarlierLandingEvenWhenItSortsFirst()
	{
		// The mirror of the tie above: here the earlier landing is the one the map reaches first.
		landings.aimed("a", 120);
		landings.settle(MISSILES, 100);
		landings.aimed("b", 140);
		landings.settle(MAGIC, 101);

		assertEquals(MISSILES, landings.take(130));
		assertEquals(MAGIC, landings.take(130));
	}

	@Test
	public void aTakenProjectileStillInFlightIsNotTakenAgainWhenReported()
	{
		Object orb = new Object();
		landings.aimed(orb, 130);
		landings.settle(MISSILES, 100);
		assertEquals(MISSILES, landings.take(130));

		// The client keeps reporting it until it is gone, after the prayers have changed.
		landings.aimed(orb, 135);
		landings.settle(0, 101);

		assertEquals(Landings.NONE, landings.take(135));
	}

	@Test
	public void aReportedTakenProjectileLeavesTheOtherOneForTheNextHit()
	{
		Object taken = new Object();
		Object other = new Object();
		landings.aimed(taken, 130);
		landings.settle(MISSILES, 100);
		landings.aimed(other, 150);
		landings.settle(MAGIC, 101);
		assertEquals(MISSILES, landings.take(130));

		landings.aimed(taken, 135);
		landings.settle(0, 102);

		assertEquals(MAGIC, landings.take(150));
		assertEquals(Landings.NONE, landings.take(150));
	}

	@Test
	public void aTakenProjectileIsForgottenOncePastTolerance()
	{
		Object orb = new Object();
		landings.aimed(orb, 100);
		landings.settle(MISSILES, 90);
		assertEquals(MISSILES, landings.take(100));

		landings.settle(0, 100 + Landings.TOLERANCE + 1);
		// Forgotten, so a report of it is a new projectile again.
		landings.aimed(orb, 400);
		landings.settle(MAGIC, 380);

		assertEquals(MAGIC, landings.take(400));
	}
}

package com.matthewmariner.prayerhitsplats;

import static com.matthewmariner.prayerhitsplats.PrayerHitsplatsPlugin.MAGIC;
import static com.matthewmariner.prayerhitsplats.PrayerHitsplatsPlugin.MELEE;
import static com.matthewmariner.prayerhitsplats.PrayerHitsplatsPlugin.MISSILES;
import static com.matthewmariner.prayerhitsplats.PrayerHitsplatsPlugin.prayedAgainst;
import static com.matthewmariner.prayerhitsplats.PrayerHitsplatsPlugin.prayedAgainstProjectile;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class PrayedAgainstTest
{
	@Test
	public void meleeIsStoppedOnlyByProtectFromMelee()
	{
		assertTrue(prayedAgainst(true, MELEE));
		assertFalse("ranged prayer against a melee hit", prayedAgainst(true, MISSILES));
		assertFalse("magic prayer against a melee hit", prayedAgainst(true, MAGIC));
	}

	@Test
	public void aHitOutOfMeleeReachIsStoppedByEitherRangedOrMagicPrayer()
	{
		assertTrue(prayedAgainst(false, MISSILES));
		assertTrue(prayedAgainst(false, MAGIC));
		assertFalse("melee prayer against a hit out of melee reach", prayedAgainst(false, MELEE));
		assertFalse("no prayer", prayedAgainst(false, 0));
	}

	@Test
	public void aProjectileHitIsStoppedByAPrayerUpWhenItWasFired()
	{
		assertTrue(prayedAgainstProjectile(MISSILES, 0));
		assertTrue(prayedAgainstProjectile(MAGIC, 0));
	}

	@Test
	public void aProjectileHitIsStoppedByAPrayerUpWhenItLanded()
	{
		assertTrue(prayedAgainstProjectile(0, MISSILES));
		assertTrue(prayedAgainstProjectile(0, MAGIC));
		assertTrue("wrong prayer at launch, right one at impact", prayedAgainstProjectile(MELEE, MAGIC));
	}

	@Test
	public void aProjectileHitIsStoppedByProtectFromMelee()
	{
		assertTrue(prayedAgainstProjectile(MELEE, 0));
		assertTrue(prayedAgainstProjectile(0, MELEE));
	}

	@Test
	public void aProjectileHitWithNoPrayerUpAtEitherMomentIsNotStopped()
	{
		assertFalse(prayedAgainstProjectile(0, 0));
	}
}

package com.matthewmariner.prayerhitsplats;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.awt.Color;
import java.awt.image.BufferedImage;
import org.junit.Test;

public class PrayerHitsplatsOverlayTest
{
	private static final Color AMBER = new Color(255, 176, 0);

	@Test
	public void tintKeepsShapeAndShadingInTheNewHue()
	{
		BufferedImage sprite = new BufferedImage(3, 1, BufferedImage.TYPE_INT_ARGB);
		sprite.setRGB(1, 0, 0xFF0040C8);
		sprite.setRGB(2, 0, 0xFF001464);

		BufferedImage tinted = PrayerHitsplatsOverlay.tint(sprite, AMBER);

		assertEquals("transparent stays transparent", 0, tinted.getRGB(0, 0) >>> 24);
		assertEquals(0xFF, tinted.getRGB(1, 0) >>> 24);
		assertEquals(hue(AMBER), hue(new Color(tinted.getRGB(1, 0))), 0.01f);
		assertTrue("the darker pixel stays darker", brightness(tinted.getRGB(2, 0)) < brightness(tinted.getRGB(1, 0)));
	}

	private static float hue(Color colour)
	{
		return Color.RGBtoHSB(colour.getRed(), colour.getGreen(), colour.getBlue(), null)[0];
	}

	private static float brightness(int rgb)
	{
		Color colour = new Color(rgb);
		return Color.RGBtoHSB(colour.getRed(), colour.getGreen(), colour.getBlue(), null)[2];
	}
}

